"""Build the two-case handoff report from already-frozen sensor and audit outputs."""
import argparse,json,pathlib,collections
import numpy as np
from tools.pointcloud_p0.replay_io import read
from integration.target_pointcloud_localization import _transform

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--output',type=pathlib.Path,required=True);ap.add_argument('--holdout-root',type=pathlib.Path,required=True);args=ap.parse_args();p=args.output;f=json.loads((p/'frozen_sensor_decisions.json').read_text());aud=json.loads((p/'offline_audit.json').read_text());owners=json.loads((p/'ownership.json').read_text());formal=json.loads((p/'formal_audit.json').read_text());e=next(x for x in f if x['case']=='holdout_extra_250_25' and x['radius_name']=='TEST');r=next(x for x in aud if x['case']==e['case'] and x['radius_name']=='TEST');m=e['decision']['current'];d,l,rgb,rad,ego,objs=read(args.holdout_root/e['case']);raw=np.frombuffer(l.raw_data,dtype=np.float32).reshape(-1,4);world=_transform(raw[:,:3],np.asarray(l.transform.get_matrix()));ego_pts=_transform(world,np.asarray(ego.get_inverse_matrix()));ranges=np.linalg.norm(ego_pts[e['candidate_cluster_ids'],:2],axis=1);iqr=float(np.percentile(ranges,75)-np.percentile(ranges,25));own=[x for x in owners if x['case']==e['case'] and x['radius_name']=='TEST'];counts=collections.Counter(x['owner'] for x in own);base=next(x for x in f if x['case']=='holdout_250_30' and x['radius_name']=='R4');d2,l2,rgb2,rad2,ego2,objs2=read(args.holdout_root/base['case']);xyz=np.frombuffer(l2.raw_data,dtype=np.float32).reshape(-1,4)[base['candidate_point_ids'],:3].astype(float);pair=np.linalg.norm(xyz[:,None,:]-xyz[None,:,:],axis=2);np.fill_diagonal(pair,np.inf);smallest=float(np.min(pair));three=float(np.min(np.partition(pair,1,axis=1)[:,1]))
 lines=['# 低置信度辅助目标的三维身份区分：两个样本验收','', '## 边界和方法','', '分支 experiment/3d-target-disambiguator-20261117 从 before-VLM-sense 创建。0.35 正式目标使用保存的正式检测与原方案 C；先冻结并保留正式点及正式框覆盖点，辅助候选在剩余点中保持唯一归属。0.52m、0.5098～0.60m 仅为这两例的离线测试。无多帧点云累积、无正式车辆控制。','', 'Target3DDisambiguator 的输入只有同帧同传感器坐标、帧内点 ID、检测框、候选簇和时间戳。它先检查重复分配、帧／传感器／时间一致性，再报告三维点距和 LiDAR 径向深度分布。单帧缺连续观测、缺经独立标定的阈值时一律 UNKNOWN；即便未来传入研究阈值和连续观测，结果也标注 unvalidated 且无控制权限。Actor 真值和语义 LiDAR 在聚类及身份结果冻结后才用于离线核验。','', '## extra_250_25：正式目标与辅助候选','', f"- 正式已选 {len(e['formal_selected_ids'])} 点；辅助剩余 {len(e['candidate_point_ids'])} 点，0.52m 形成 {len(e['candidate_cluster_ids'])} 点候选簇。原始点 ID 交集 {len(m['duplicate_point_ids'])}。", f"- 归属明细：正式选中 {counts['FORMAL_SELECTED']}，辅助簇 {counts['AUX_CLUSTER_UNVALIDATED']}，辅助未选 {counts['AUX_CANDIDATE_UNASSIGNED']}，正式保护但未选 {counts['FORMAL_PROTECTED_NOT_SELECTED']}，过滤或歧义未分配 {counts['FILTERED_OR_AMBIGUOUS_UNASSIGNED']}。",f"- 正式簇 LiDAR 径向范围 {m['formal_radial_range_m'][0]:.3f}～{m['formal_radial_range_m'][1]:.3f}m；辅助簇 {m['auxiliary_radial_range_m'][0]:.3f}～{m['auxiliary_radial_range_m'][1]:.3f}m；区间间隔 {m['radial_interval_gap_m']:.3f}m，两簇最近三维点距 {m['nearest_3d_points_m']:.3f}m。", '- 两簇呈现明显的单帧空间分离，与人工判断不同车辆一致；但缺少连续帧与独立标定准则，且不能仅凭分离排除簇内多物体混合。结论不是已经独立确认两个物理目标。','', '## holdout_250_30 / C-0002：半径扫描','', f'本帧 0.35 正式检测为 0；13 个辅助候选点与另一辅助候选 5 点在帧内唯一分离。13 点最小两点间距 {smallest:.4f}m，形成任意三点连通的几何下限 {three:.4f}m。另一候选是辅助目标，不能当作正式目标。','', '|半径 m|几何簇数|选中点|Precision|条件 Recall|误合并|状态|','|---:|---:|---:|---:|---:|---|---|']
 for a in aud:
  if a['case']!='holdout_250_30' or a['radius_name']=='R0_exact':continue
  lines.append(f"|{a['radius_m']:.4f}|{a['component_count']}|{a['cluster_point_count']}|未定义|{a['point_recall_conditional']*100:.1f}%|无选中簇，无法评估|{a['status']}|")
 lines += ['', '近似语义核验：13 个候选点中 12 个匹配自动目标，1 个匹配环境或其他；自动角色仍由 IoU 匹配得到。所有请求半径均未形成 3 点簇，不能说已成功恢复目标，也不能把误合并次数报告为经过验证的 0。','', '## 七项指标和状态','', '|指标|extra_250_25：0.52m|250_30：0.5098～0.60m|','|---|---|---|',f"|目标点级 Precision|{r['target_approx']}/{r['cluster_point_count']} = {r['point_precision']*100:.1f}%|无选中点，未定义|",f"|条件点级 Recall|{r['target_approx']}/{r['recall_denominator_eligible_target_approx']} = {r['point_recall_conditional']*100:.2f}%|0/12 = 0%，分母为过滤后近似目标点|",'|不同车辆错误合并|所选 1 簇中近似其他车辆点 0；单例不足以泛化|无选中簇，无法评估|','|形成的簇|1 个 11 点几何候选；可信定位 0|全部 0|',f"|表面测距误差|{r['surface_signed_error_m']:+.3f}m，单帧对离线包围盒最近水平表面|无选中簇，无法计算|",f"|位置估计不确定性|未标定；水平距离 IQR {iqr:.3f}m 只是点分散度|未输出|",'|正式检测链路|保存的正式检测输入下，方案 C 全部输出字段前后相同|本帧无正式检测，方案 C 输出前后相同|','', '两例最终均为 UNKNOWN。前者缺连续观测、阈值未标定；后者另缺正式目标和辅助点簇。两例均不进入 FOLLOW。正式检测模型、跟踪、车道判断、控制和动态运行没有在本轮端到端测试，不能声称完整驾驶链路验收。','', '## 验证和代码清单','', '13 个身份模块测试、原有点云定位／分组／审计测试合计 27 个通过；verify_two_samples.py 独立重算点距、深度间隔和 8 个冻结策略的唯一归属。两帧方案 C 处理前后返回字段一致。','', '新增文件位于 tools/pointcloud_p0/target3d_experiment/：disambiguator.py、run_two_samples.py、verify_two_samples.py、test_disambiguator.py、visualization.html、interactive_3d.html、prepare_camera_views.py、README.md、__init__.py、summarize_results.py。没有修改 YOLO 阈值／权重、正式方案 C、Teacher、Student 或 A/B/C/D。','', '结果文件：frozen_sensor_decisions.json（真值核验前决策）、offline_audit.json（事后指标）、point_ownership.csv（逐点归属）、formal_audit.json（基线对比）、visualization.html / visualization.json（三维图）。分支代码尚未提交 Git commit，待用户验收。']
 (p/'report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8');print('report written',p/'report.md')
if __name__=='__main__':main()
